// IntegrationServiceServer is the server API for IntegrationService service.
// All implementations must embed UnimplementedIntegrationServiceServer
// for forward compatibility.
type IntegrationServiceServer interface {
	ConnectIntegration(context.Context, *ConnectIntegrationRequest) (*ConnectIntegrationResponse, error)
	DisconnectIntegration(context.Context, *DisconnectIntegrationRequest) (*emptypb.Empty, error)
	GetIntegrations(context.Context, *GetIntegrationsRequest) (*GetIntegrationsResponse, error)
	// ValidateInstallation resolves the installing account + tenant kind WITHOUT
	// persisting credentials (the resolve step of pin-before-save). It consumes the
	// CSRF state, proves OAuth user access, and returns a single-use save receipt. The caller pins the resolved owner before calling SaveInstallation.
	ValidateInstallation(context.Context, *ValidateInstallationRequest) (*ValidateInstallationResponse, error)
	// SaveInstallation persists the credential for an installation the caller has
	// already validated (ValidateInstallation) and owner-verified
	// (PinIndividualOwner). Nothing is persisted before the owner pin succeeds. For
	// an INDIVIDUAL tenant it re-resolves the installation and rejects BEFORE
	// persisting if the account differs from request.expected_account_id (a
	// pre-persist torn-state guard).
	SaveInstallation(context.Context, *SaveInstallationRequest) (*SaveInstallationResponse, error)
	ValidateAndSaveBitbucketConnection(context.Context, *ValidateAndSaveBitbucketConnectionRequest) (*ValidateAndSaveBitbucketConnectionResponse, error)
	ValidateAndSaveSlackConnection(context.Context, *ValidateAndSaveSlackConnectionRequest) (*ValidateAndSaveSlackConnectionResponse, error)
	HandleWebhook(context.Context, *HandleWebhookRequest) (*emptypb.Empty, error)
	GetBitbucketWorkspaces(context.Context, *GetBitbucketWorkspacesRequest) (*GetBitbucketWorkspacesResponse, error)
	SelectBitbucketWorkspace(context.Context, *SelectBitbucketWorkspaceRequest) (*emptypb.Empty, error)
	ValidateAndSaveJiraConnection(context.Context, *ValidateAndSaveJiraConnectionRequest) (*ValidateAndSaveJiraConnectionResponse, error)
	SelectJiraCloudSite(context.Context, *SelectJiraCloudSiteRequest) (*emptypb.Empty, error)
	ValidateAndSaveGitLabConnection(context.Context, *ValidateAndSaveGitLabConnectionRequest) (*ValidateAndSaveGitLabConnectionResponse, error)
	GetGitLabGroups(context.Context, *GetGitLabGroupsRequest) (*GetGitLabGroupsResponse, error)
	SelectGitLabGroup(context.Context, *SelectGitLabGroupRequest) (*emptypb.Empty, error)
	// HandleGitLabWebhook ingests a GitLab webhook delivery. GitLab posts every
	// org's events to one shared endpoint with no org identifier, so the handler
	// scans all connector configs to match the X-Gitlab-Token secret before it
	// knows the org — a cross-tenant read. Hence SYSTEM scope; ENFORCED would
	// reject the org-less request. The handler emits only for the matched org.
	HandleGitLabWebhook(context.Context, *HandleGitLabWebhookRequest) (*emptypb.Empty, error)
	ValidateAndSaveLinearConnection(context.Context, *ValidateAndSaveLinearConnectionRequest) (*ValidateAndSaveLinearConnectionResponse, error)
	GetVCSSettings(context.Context, *GetVCSSettingsRequest) (*GetVCSSettingsResponse, error)
	UpdateVCSSettings(context.Context, *UpdateVCSSettingsRequest) (*emptypb.Empty, error)
	ListVCSRepos(context.Context, *ListVCSReposRequest) (*ListVCSReposResponse, error)
	// ValidateConnectorToken validates a pasted credential and returns the vendor
	// account it authenticates as WITHOUT persisting anything (the resolve step of
	// pin-before-save). The caller pins the resolved owner before calling
	// SubmitConnectorToken.
	ValidateConnectorToken(context.Context, *ValidateConnectorTokenRequest) (*ValidateConnectorTokenResponse, error)
	// SubmitConnectorToken persists a pasted credential the caller has already
	// validated (ValidateConnectorToken) and owner-verified (PinIndividualOwner).
	// Nothing is persisted before the owner pin succeeds.
	SubmitConnectorToken(context.Context, *SubmitConnectorTokenRequest) (*SubmitConnectorTokenResponse, error)
	// ValidateCursorTeamKey resolves a pasted Cursor team key to the members it
	// authenticates for, persisting nothing. A key that lists members but cannot read
	// billed usage events is refused: every scheduled run depends on that privilege.
	ValidateCursorTeamKey(context.Context, *ValidateCursorTeamKeyRequest) (*ValidateCursorTeamKeyResponse, error)
	// SubmitCursorTeamKey persists a Cursor team key the administrator has confirmed
	// and enables the connector. It re-runs both probes before saving.
	SubmitCursorTeamKey(context.Context, *SubmitCursorTeamKeyRequest) (*SubmitCursorTeamKeyResponse, error)
	// ValidateAnthropicAnalyticsKey resolves a pasted Anthropic Analytics API key to the
	// organisation and members it authenticates for, persisting nothing. It probes once
	// per scope: a key that reads the roster but not the analytics endpoints, or the
	// reverse, is refused — every scheduled run depends on both, and a key's scopes
	// cannot be widened after creation.
	ValidateAnthropicAnalyticsKey(context.Context, *ValidateAnthropicAnalyticsKeyRequest) (*ValidateAnthropicAnalyticsKeyResponse, error)
	// SubmitAnthropicAnalyticsKey persists a key the administrator has confirmed and
	// enables the connector. It re-runs both probes before saving.
	SubmitAnthropicAnalyticsKey(context.Context, *SubmitAnthropicAnalyticsKeyRequest) (*SubmitAnthropicAnalyticsKeyResponse, error)
	// ValidateCodexAnalyticsKey resolves a pasted Codex Analytics admin key against the
	// workspace the administrator named, persisting nothing. One scope covers the endpoint,
	// so one probe proves exactly the privilege every scheduled run depends on. A rejected
	// key, a key without the scope, and an unreachable workspace are each refused
	// distinguishably, because an administrator cannot act on a single opaque failure.
	ValidateCodexAnalyticsKey(context.Context, *ValidateCodexAnalyticsKeyRequest) (*ValidateCodexAnalyticsKeyResponse, error)
	// SubmitCodexAnalyticsKey persists a Codex Analytics admin key and workspace the
	// administrator has confirmed and enables the connector. It re-probes before saving.
	// The workspace this request names replaces whatever is stored, so a reconnect
	// re-points the connector rather than keeping the old workspace.
	SubmitCodexAnalyticsKey(context.Context, *SubmitCodexAnalyticsKeyRequest) (*SubmitCodexAnalyticsKeyResponse, error)
	// ConfirmConnectorRepos confirms the repos to track and enables the connector.
	ConfirmConnectorRepos(context.Context, *ConfirmConnectorReposRequest) (*emptypb.Empty, error)
	// DisableConnectorConfigsForOrg disables every enabled connector config owned
	// by request.org_id and returns the count. It is idempotent, so a caller can
	// repeat it. SYSTEM scope: the caller runs cross-tenant and names the org in
	// the request body, which ENFORCED would reject.
	DisableConnectorConfigsForOrg(context.Context, *DisableConnectorConfigsForOrgRequest) (*DisableConnectorConfigsForOrgResponse, error)
	// ValidateKiroBucket builds the read policy for a customer's reports bucket and reports
	// what it could see there, persisting nothing. It fetches exactly one object when one
	// exists: a grant that lists but cannot read lets every listing pass and every fetch
	// fail, so a listing-only check would save a connector that cannot collect and the
	// failure would surface on the first scheduled run with nobody watching.
	ValidateKiroBucket(context.Context, *ValidateKiroBucketRequest) (*ValidateKiroBucketResponse, error)
	// SubmitKiroBucket persists a bucket the administrator has confirmed and enables the
	// connector. It re-runs the same walk and probe, and stores only what it observed.
	SubmitKiroBucket(context.Context, *SubmitKiroBucketRequest) (*SubmitKiroBucketResponse, error)
	mustEmbedUnimplementedIntegrationServiceServer()
}

